@pytest.mark.parametrize(("label", "raw", "expected"), VALIDATION_CASES)
def test_typescript_validation_contract(label, raw, expected):
    assert validate_def(raw, "t.yaml") == expected, label


def write_def(root, name, folder=False, body=None):
    path = root / name / "workflow.yaml" if folder else root / f"{name}.yaml"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(body if body is not None else f"version: 2\nname: {name}\ndescription: d\nsteps: []\n")
    return path


def test_discovery(tmp_path):
    user, bundled = tmp_path / "user", tmp_path / "bundled"
    roots = {"user_root": user, "bundled_root": bundled}
    path = write_def(bundled, "wf", True)
    assert locate_def("wf", roots) == {"name": "wf", "path": str(path), "dir": str(path.parent), "source": "bundled"}
    path = write_def(user, "wf")
    assert locate_def("wf", roots) == {"name": "wf", "path": str(path), "dir": "", "source": "user"}
    path = write_def(user, "wf", True)
    assert locate_def("wf", roots)["path"] == str(path)
    assert locate_def("missing", roots) is None
    for name in RESERVED_NAMES:
        write_def(user, name)
        assert locate_def(name, roots) is None
    alias = tmp_path / "alias"
    alias.symlink_to(user, target_is_directory=True)
    assert locate_def("wf", {**roots, "user_root": alias})["path"] == str(alias / "wf/workflow.yaml")


def test_default_roots():
    result = default_roots(env={"XDG_DATA_HOME": "/x"}, home="/h")
    assert result["user_root"] == "/x/wise/workflows/definitions"
    assert result["bundled_root"].endswith("/plugins/wise/workflows")
    for env, expected in [({"CLAUDE_PLUGIN_DATA": "/c"}, "/c"), ({"WISE_DATA_DIR": "/w"}, "/w"), ({}, "/h/.local/share/wise")]:
        assert default_roots(env=env, home="/h")["user_root"] == expected + "/workflows/definitions"


def test_load_errors_and_null(tmp_path):
    for text in ("", "null", "~"):
        assert load_def(write_def(tmp_path, "empty", body=text)) == {}
    with pytest.raises(Exception):
        load_def(write_def(tmp_path, "bad", body="steps: [\n"))
    with pytest.raises(OSError):
        load_def(tmp_path / "missing")
    with pytest.raises(ValueError, match="unique"):
        load_def(write_def(tmp_path, "dup", body="x: 1\nx: 2\n"))
    path = write_def(tmp_path, "good", body="version: 2\nname: good\nsteps: [{id: a, type: bash, run: 'true'}]\n")
    assert load_and_validate({"path": str(path)})["def"]["name"] == "good"


def test_listing(tmp_path):
    user, bundled = tmp_path / "user", tmp_path / "bundled"
    roots = {"user_root": user, "bundled_root": bundled}
    write_def(bundled, "shared", True)
    write_def(bundled, "only-bundled", body="name: renamed\ndescription: '  spaced  '\n")
    write_def(user, "shared")
    folder = write_def(user, "both", True)
    write_def(user, "both")
    write_def(user, "broken", body="steps: [\n")
    items = list_defs(roots)
    assert [(r["name"], r["source"], r["shadowed"]) for r in items] == [("both", "user", False), ("broken", "user", False), ("shared", "user", False), ("shared", "bundled", True), ("renamed", "bundled", False)]
    assert items[0]["path"] == str(folder)
    assert items[1]["description"].startswith("<unreadable: ")
    assert items[-1]["description"] == "spaced"
    write_def(bundled, "broken")
    assert not next(x for x in list_defs(roots) if x["name"] == "broken" and x["source"] == "bundled")["shadowed"]
    assert list_defs({"user_root": tmp_path / "none", "bundled_root": tmp_path / "none2"}) == []


def test_plugin_detection(tmp_path):
    root = tmp_path / "plugins"
    assert installed_plugins(plugins_root=root) == set()
    root.mkdir()
    registry = root / "installed_plugins.json"
    registry.write_text(json.dumps({"plugins": {"wise@market": {}, "bare": {}}}))
    assert installed_plugins(plugins_root=root) == {"wise", "bare"}
    for directory, text in {"cache/market/named/1.2.3": '{"name":"real-name"}', "cache/market/nameless/0.1": "{not json", "flat-plugin": "{}", "cache/market/too/deep/five": '{"name":"not-found"}'}.items():
        path = root / directory / ".claude-plugin/plugin.json"
        path.parent.mkdir(parents=True)
        path.write_text(text)
    assert installed_plugins(plugins_root=root) == {"wise", "bare"}
    for content in ("{broken", '{"plugins": []}'):
        registry.write_text(content)
        assert installed_plugins(plugins_root=root) == {"flat-plugin", "nameless", "real-name"}


def test_requirements(tmp_path):
    definition = {"requires": {"plugins": ["wise", "other"], "tools": ["gh", "absent"]}}
    assert probe_requires(definition, installed={"wise"}, has_tool=lambda n: n == "gh") == {"ok": False, "missing": ["plugin:other", "tool:absent"]}
    assert probe_requires({}, installed=set()) == {"ok": True, "missing": []}
    (tmp_path / "installed_plugins.json").write_text('{"plugins":{"wise@m":{}}}')
    assert probe_requires({"requires": {"plugins": ["wise"]}}, plugins_root=tmp_path)["ok"]
    executable = tmp_path / "tool"
    executable.write_text("fixture")
    executable.chmod(0o600)
    assert not on_path("tool", {"PATH": str(tmp_path)})
    executable.chmod(0o700)
    assert on_path("tool", {"PATH": f":{tmp_path}:"})
    assert not on_path("tool", {"PATH": ""})


def test_input_listing():
    inputs = [{"name": "a"}, {"name": "b", "prompt": "B?", "optional": True, "from-context": "guidance", "extract": "(x+)", "validate": "x+"}]
    assert list_inputs({"inputs": inputs}) == [{"name": "a", "prompt": "Value for a?"}, inputs[1]]
    assert list_inputs({}) == []
    assert list_inputs({"inputs": [{"name": "a", "prompt": ""}]}) == [{"name": "a", "prompt": ""}]
    for path in ("guidance", "ticket[].ref", "ticket[].url", "links[]", "decisions.db-choice"):
        assert FROM_CONTEXT_RE.search(path)
    for path in ("ticket", "ticket[].nope", "decisions", "links"):
        assert not FROM_CONTEXT_RE.search(path)


@pytest.mark.parametrize(("raw", "extract", "validate", "expected"), [
    ("see KEY-772 now", r"([A-Z]+-\d+)", None, {"ok": True, "value": "KEY-772"}),
    ("see KEY-772 now", r"[A-Z]+-\d+", None, {"ok": True, "value": "KEY-772"}),
    ("nothing", r"\d+", None, {"ok": False, "reason": "no-match", "message": "INVALID:no-match"}),
    ("ask", None, "defaults|ask", {"ok": True, "value": "ask"}),
    ("asking", None, "defaults|ask", {"ok": False, "reason": "validate", "message": "INVALID:validate"}),
    ("raw", "", "", {"ok": True, "value": "raw"}),
    ("b", "(a)?b", None, {"ok": True, "value": ""}),
    ("abc", "(?<name>a)b", None, {"ok": True, "value": "a"}),
])
def test_validate_input(raw, extract, validate, expected):
    assert validate_input(raw, extract, validate) == expected


def test_invalid_regexes():
    assert validate_input("x", "(")["reason"] == "bad-extract-regex"
    assert validate_input("x", None, "(")["reason"] == "bad-validate-regex"
    assert not validate_input("٣", r"\d")["ok"]


def test_bundled_and_v1_definitions():
    engine = Path(__file__).resolve().parents[1]
    expected = {"ticket-plan": 16, "example-workflow": 8, "ticket-auto": 5, "impl-plan-auto": 4, "code-review": 12}
    items = list_defs({"user_root": engine / "no-user", "bundled_root": engine.parent / "workflows"})
    assert sorted(x["name"] for x in items) == sorted(expected)
    for item in items:
        result = validate_def(load_def(item["path"]), item["path"])
        assert result["issues"] == [], item["name"]
        assert len(result["def"]["steps"]) == expected[item["name"]]
    for name in ("impl-plan-auto", "ticket-auto"):
        path = engine / "test/fixtures/migrate" / f"{name}.v1.yaml"
        result = validate_def(load_def(path), str(path))
        assert "def" not in result
        hints = [x for x in result["issues"] if x["level"] == "error" and x.get("hint")]
        assert any(x["path"] == "version" and "version: 2" in x["hint"] for x in hints)
        assert any(x["path"].startswith("steps[") and x["path"].endswith(".type") for x in hints)
        if name == "ticket-auto":
            assert any(x["path"] == "tuning.groups[0].default" and "{ harness: claude, model: opus, effort: high }" in x["hint"] for x in hints)
            assert any(x["path"] == "steps[5].type" and "type: units" in x["hint"] for x in hints)
        else:
            assert any(x["path"] == "preflight.rename_session" and "drop it" in x["hint"] for x in hints)


def test_yaml_core_scalars():
    data = parse_yaml("date: 2026-09-11\non: off\nyes: no\nint: 012\nexp: 1e3\nbig: 9007199254740993\nx: &a {v: 1}\ny: {<<: *a}\nbin: 0b101\nunderscore: 1_000\n")
    assert data == {"date": "2026-09-11", "on": "off", "yes": "no", "int": 12, "exp": 1000, "big": 9007199254740992, "x": {"v": 1}, "y": {"<<": {"v": 1}}, "bin": "0b101", "underscore": "1_000"}
    assert list(parse_yaml("true: a\n1: b\n")) == ["1", "true"]
    assert parse_yaml('a: "true"\nb: !!str 2\nc: null\n') == {"a": "true", "b": "2", "c": None}
    assert math.isinf(parse_yaml("v: .inf")["v"])
    assert math.isnan(parse_yaml("v: .NaN")["v"])


def test_missing_null_and_numeric_types():
    base = {"version": 2, "name": "t", "steps": [{"id": "a", "type": "agent", "prompt": "x"}]}
    for key in ("tuning", "profiles", "inputs", "step-select", "requires", "preflight"):
        assert validate_def({**base, key: None}, "t.yaml")["def"] == base
    for key in ("harness", "model", "effort", "auth", "fallback", "mode", "resume", "max_turns", "timeout", "stale_after", "allowed_tools", "allow-api", "mcp", "optional"):
        assert "def" not in validate_def({**base, "steps": [{**base["steps"][0], key: None}]}, "t.yaml")
    for number in (True, False, 0, 1.5, math.inf, math.nan):
        assert "def" not in validate_def({**base, "steps": [{**base["steps"][0], "max_turns": number}]}, "t.yaml")
    assert "def" in validate_def({**base, "steps": [{**base["steps"][0], "max_turns": 1.0}]}, "t.yaml")
    for value, expected in ((True, "true"), (False, "false"), (1.0, "1"), (1e-7, "1e-7"), (math.inf, "Infinity")):
        assert validate_def({**base, "inputs": [{"name": "x", "default": value}]}, "t.yaml")["def"]["inputs"][0]["default"] == expected
    assert "def" not in validate_def({**base, "version": True}, "t.yaml")
